<script setup>
import { ref,computed } from 'vue'
import { api,state,refresh,notify,speak } from '../api'
import Icon from '../components/Icon.vue'
const mode=ref('choice'),topic=ref(''),count=ref(10),session=ref(null),position=ref(0),answers=ref([]),result=ref(null),selected=ref(null),text=ref(''),busy=ref(false),error=ref('')
const question=computed(()=>session.value?.questions[position.value]),done=computed(()=>session.value && position.value>=session.value.questions.length),score=computed(()=>answers.value.filter(a=>a.correct).length)
async function start(){busy.value=true;error.value='';try{session.value=await api('/quiz',{method:'POST',body:JSON.stringify({mode:mode.value,topic_id:topic.value ? Number(topic.value) : null,count:count.value})});position.value=0;answers.value=[];result.value=null;selected.value=null;text.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
async function submit(){if(busy.value || result.value)return;busy.value=true;error.value='';try{result.value=await api(`/quiz/${session.value.id}/answer`,{method:'POST',body:JSON.stringify({position:position.value,option_id:selected.value,text:text.value})});answers.value.push(result.value);refresh().catch(e=>notify(e.message))}catch(e){error.value=e.message}finally{busy.value=false}}
function next(){position.value++;result.value=null;selected.value=null;text.value='';error.value=''}
</script>
<template><div class="page practice-page"><div class="page-heading"><div><div class="eyebrow">BIẾN TỪ VỰNG THÀNH PHẢN XẠ</div><h1>Luyện một chút, nhớ thêm một chút</h1><p>Kiểm tra những gì bạn nhớ. Mỗi câu sai là một cơ hội học lại.</p></div></div>
<section v-if="!session" class="practice-setup"><div class="setup-intro"><span class="stat-icon green"><Icon name="Target" :size="28"/></span><h2>Bạn muốn luyện thế nào?</h2><p>Chọn một cách học phù hợp với hôm nay.</p></div><div class="practice-modes"><button :class="['mode-card',{selected:mode==='choice'}]" @click="mode='choice'"><Icon name="ListChecks" :size="30"/><h3>Chọn đúng nghĩa</h3><p>Nhìn từ tiếng Anh và chọn nghĩa tiếng Việt.</p><span>{{mode==='choice' ? 'Đã chọn' : 'Chọn chế độ'}}<Icon :name="mode==='choice' ? 'CircleCheck' : 'ArrowRight'" :size="18"/></span></button><button :class="['mode-card',{selected:mode==='typing'}]" @click="mode='typing'"><Icon name="Keyboard" :size="30"/><h3>Nhớ & gõ từ</h3><p>Nhìn nghĩa tiếng Việt và tự gõ từ tiếng Anh.</p><span>{{mode==='typing' ? 'Đã chọn' : 'Chọn chế độ'}}<Icon :name="mode==='typing' ? 'CircleCheck' : 'ArrowRight'" :size="18"/></span></button></div><form @submit.prevent="start"><div class="study-controls"><label>Chủ đề<select v-model="topic"><option value="">Trộn tất cả chủ đề</option><option v-for="t in state.topics" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Số câu<select v-model.number="count"><option :value="5">5 câu · Khởi động</option><option :value="10">10 câu · Vừa đủ</option><option :value="20">20 câu · Thử thách</option></select></label></div><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="btn primary full" :disabled="busy">{{busy ? 'Đang chuẩn bị…' : 'Bắt đầu luyện tập'}}<Icon name="ArrowRight" :size="18"/></button></form></section>
<section v-else-if="done" class="session-complete"><div class="complete-icon"><Icon name="Award" :size="44"/></div><div class="eyebrow">BẠN ĐÃ HOÀN THÀNH</div><h2>{{score}} / {{session.questions.length}} câu đúng</h2><p>{{score===session.questions.length ? 'Rất tốt! Bạn đã nhớ hết các từ trong lượt này.' : 'Những từ trả lời sai đã được đưa vào lịch ôn sớm.'}}</p><div class="answer-summary"><div v-for="(a,i) in answers" :key="i"><Icon :name="a.correct ? 'CircleCheck' : 'CircleX'" :size="18" :class="a.correct ? 'correct-text' : 'wrong-text'"/><strong>{{a.word.term}}</strong><span>{{a.word.meaning}}</span></div></div><div class="heading-actions"><button class="btn primary" @click="session=null">Luyện bài mới<Icon name="ArrowRight" :size="18"/></button><RouterLink to="/study?mode=due" class="btn outline">Ôn từ đến hạn</RouterLink></div></section>
<div v-else class="quiz-workspace"><div class="study-progress"><span>CÂU {{position+1}} / {{session.questions.length}}</span><span>{{score}} câu đúng</span><div class="progress-track"><span :style="{width:position/session.questions.length*100+'%'}"></span></div></div><section class="quiz-card"><div class="eyebrow">{{session.mode==='choice' ? 'CHỌN NGHĨA ĐÚNG CỦA TỪ' : 'TỪ TIẾNG ANH TƯƠNG ỨNG LÀ GÌ?'}}</div><h2>{{question.prompt}}</h2><button v-if="session.mode==='choice'" class="audio-button" aria-label="Nghe từ trong câu hỏi" @click="speak(question.prompt)"><Icon name="Volume2" :size="20"/>Nghe phát âm</button><form @submit.prevent="submit"><div v-if="session.mode==='choice'" class="quiz-options"><button v-for="(option,i) in question.options" :key="option.id" type="button" :class="['quiz-option',{selected:selected===option.id,correct:result?.word.id===option.id,wrong:result && !result.correct && selected===option.id}]" :disabled="!!result || busy" :aria-pressed="selected===option.id" @click="selected=option.id"><span>{{String.fromCharCode(65+i)}}</span>{{option.label}}<Icon v-if="result?.word.id===option.id" name="Check" :size="20"/></button></div><label v-else class="typing-label">Câu trả lời của bạn<input v-model="text" :disabled="!!result || busy" placeholder="Gõ từ hoặc cụm từ tiếng Anh…" autocomplete="off" autocapitalize="off" spellcheck="false"/></label><div v-if="result" :class="['answer-feedback',result.correct ? 'good' : 'bad']" role="status"><strong><Icon :name="result.correct ? 'CircleCheck' : 'CircleX'" :size="20"/>{{result.correct ? 'Chính xác!' : 'Chưa đúng — cùng nhớ lại nhé.'}}</strong><p><b>{{result.word.term}}</b> — {{result.word.meaning}}</p><small>{{result.word.example}}</small><button type="button" class="icon-button" aria-label="Nghe đáp án" @click="speak(result.word.term)"><Icon name="Volume2" :size="20"/></button></div><p v-if="error" class="form-error" role="alert">{{error}}</p><button v-if="!result" class="btn primary full" :disabled="busy || (session.mode==='choice' ? selected===null : !text.trim())">{{busy ? 'Đang kiểm tra…' : 'Kiểm tra đáp án'}}</button><button v-else type="button" class="btn primary full" @click="next">{{position===session.questions.length-1 ? 'Xem kết quả' : 'Câu tiếp theo'}}<Icon name="ArrowRight" :size="18"/></button></form></section><button class="muted-link exit-practice" @click="session=null">Kết thúc lượt luyện này</button></div>
</div></template>
